const $=id=>document.getElementById(id);const notice=s=>$('notice').textContent=s;
const pages={requests:['admin.html','Demandes'],crm:['crm.html','CRM'],quotes:['quotes.html','Devis'],tenders:['tenders.html','Appels d’offres'],consultants:['consultants.html','Consultants'],missions:['missions.html','Missions'],billing:['billing.html','Finance'],direction:['direction.html','Direction'],accounts:['accounts.html','Comptes'],audit:['audit.html','Journal'],'my-activity':['my-activity.html','Mes CRA']};
async function api(action,data){const r=await fetch('/api/auth/'+action,{method:data?'POST':'GET',headers:{'Content-Type':'application/json',Authorization:'Bearer session','X-DSIG-Session':'cookie'},...(data?{body:JSON.stringify(data)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error);return d}
function show(d){$('role').textContent=d.role;$('modules').replaceChildren();for(const [resource,[url,label]] of Object.entries(pages)){const mode=d.permissions[resource]||d.permissions['*'];if(!mode)continue;const a=document.createElement('a');a.className='count';a.href=url;a.textContent=label+' — '+(mode.includes('W')?'Lecture / écriture':'Lecture');$('modules').append(a)}$('workspace').hidden=false;$('login').hidden=true;notice('Connecté.')}
function reset(){$('workspace').hidden=true;$('login').hidden=false;$('secret').value='';$('mfa-pending').hidden=true;$('modules').replaceChildren()}
for(const [id,action] of [['activate','activate'],['signin','login'],['mfa-setup','mfa-setup'],['mfa-confirm','mfa-confirm']])$(id).onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const d=await api(action,Object.fromEntries(new FormData(e.target)));e.target.reset();if(action==='activate')notice('Activation effectuée. Connectez-vous.');else if(action==='login')show(d);else if(action==='mfa-setup'){$('secret').value=d.secret;$('mfa-pending').hidden=false;notice('Configurez puis confirmez le code.')}else{reset();notice('MFA activée. Reconnectez-vous avec un nouveau code.')}}catch(err){notice(err.message)}finally{b.disabled=false}};
$('logout').onclick=async()=>{try{await api('logout',{});reset();notice('Session révoquée.')}catch(e){notice(e.message)}};api('me').then(show).catch(()=>{});
